package com.lighthousepark.intervalsgym.core

private data class EuropeanAppTextTranslation(
    val korean: String,
    val german: String,
    val french: String,
    val italian: String,
    val spanish: String,
    val portuguese: String,
) {
    fun text(language: AppLanguage): String? {
        return when (language) {
            AppLanguage.GERMAN -> german
            AppLanguage.FRENCH -> french
            AppLanguage.ITALIAN -> italian
            AppLanguage.SPANISH -> spanish
            AppLanguage.PORTUGUESE -> portuguese
            else -> null
        }
    }
}

private fun europeanTranslation(
    korean: String,
    german: String,
    french: String,
    italian: String,
    spanish: String,
    portuguese: String,
): EuropeanAppTextTranslation {
    return EuropeanAppTextTranslation(
        korean = korean,
        german = german,
        french = french,
        italian = italian,
        spanish = spanish,
        portuguese = portuguese
    )
}

